import java.util.PriorityQueue;
import java.util.Comparator;

public class CustomPriorityDemo {
    static class Incident {
        final String ticketId;
        final int severity; // 1 = Critical, 2 = High, 3 = Normal
        final long timestamp;

        Incident(String ticketId, int severity, long timestamp) {
            this.ticketId = ticketId;
            this.severity = severity;
            this.timestamp = timestamp;
        }

        @Override
        public String toString() {
            return String.format("[%s: P%d, t=%d]", ticketId, severity, timestamp);
        }
    }

    public static void main(String[] args) {
        // Primary: lower severity number = higher priority;
        // Secondary tie-breaker: earlier timestamp first (FIFO)
        Comparator<Incident> triageComparator = Comparator
            .comparingInt((Incident i) -> i.severity)
            .thenComparingLong(i -> i.timestamp);

        PriorityQueue<Incident> triageQueue = new PriorityQueue<>(triageComparator);

        triageQueue.offer(new Incident("INC-101", 3, 1000L)); // Normal, t=1000
        triageQueue.offer(new Incident("INC-102", 1, 1050L)); // Critical, t=1050
        triageQueue.offer(new Incident("INC-103", 2, 1020L)); // High, t=1020
        triageQueue.offer(new Incident("INC-104", 1, 1010L)); // Critical, t=1010

        System.out.println("Dispatched Incidents:");
        while (!triageQueue.isEmpty()) {
            System.out.println("Processing: " + triageQueue.poll());
        }
    }
}
// Expected Output:
// Dispatched Incidents:
// Processing: [INC-104: P1, t=1010]
// Processing: [INC-102: P1, t=1050]
// Processing: [INC-103: P2, t=1020]
// Processing: [INC-101: P3, t=1000]

