import java.util.PriorityQueue;
import java.util.Collections;

public class LeaderboardEngine {
    public static void main(String[] args) {
        // Construct Max-Heap using Collections.reverseOrder()
        PriorityQueue<Integer> maxScores = new PriorityQueue<>(Collections.reverseOrder());

        maxScores.offer(450);
        maxScores.offer(1200);
        maxScores.offer(890);
        maxScores.offer(2100);
        maxScores.offer(650);

        System.out.println("Highest score (peek): " + maxScores.peek()); // 2100

        System.out.println("Extracting leaderboard ranks:");
        int rank = 1;
        while (!maxScores.isEmpty() && rank <= 3) {
            System.out.printf("Rank %d: %d points%n", rank++, maxScores.poll());
        }
    }
}

