import java.util.PriorityQueue;
import java.util.Comparator;
import java.util.concurrent.atomic.AtomicLong;

public class StablePriorityQueue<T> {
    private static final AtomicLong SEQ_GENERATOR = new AtomicLong();

    private static class Entry<T> {
        final T item;
        final int priority;
        final long sequenceNumber;

        Entry(T item, int priority, long sequenceNumber) {
            this.item = item;
            this.priority = priority;
            this.sequenceNumber = sequenceNumber;
        }
    }

    private final PriorityQueue<Entry<T>> pq = new PriorityQueue<>(
        Comparator.<Entry<T>>comparingInt(e -> e.priority)
                  .thenComparingLong(e -> e.sequenceNumber)
    );

    public void offer(T item, int priority) {
        pq.offer(new Entry<>(item, priority, SEQ_GENERATOR.getAndIncrement()));
    }

    public T poll() {
        Entry<T> entry = pq.poll();
        return entry != null ? entry.item : null;
    }

    public boolean isEmpty() {
        return pq.isEmpty();
    }

    public static void main(String[] args) {
        StablePriorityQueue<String> spq = new StablePriorityQueue<>();
        spq.offer("JobA", 2);
        spq.offer("JobB", 1);
        spq.offer("JobC", 2);
        spq.offer("JobD", 1);

        while (!spq.isEmpty()) {
            System.out.print(spq.poll() + " ");
        }
        System.out.println();
    }
}

